<script setup>
import { ref } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import MUpload from '../../../components/mds/MUpload.vue';
defineProps({ loading: Boolean, error: String }); const emit = defineEmits(['cancel', 'extract']); const text = ref(''); const url = ref(''); const file = ref(null); const localError = ref(''); function select(files) { file.value = files[0] || null; } function submit() { const sourceCount = Number(Boolean(file.value)) + Number(Boolean(text.value.trim())) + Number(Boolean(url.value.trim())); if (!sourceCount) { localError.value = 'Hãy dán nội dung, nhập URL hoặc chọn một tệp.'; return; } if (sourceCount > 1) { localError.value = 'Chỉ chọn một nguồn để AI bóc tách chính xác.'; return; } localError.value = ''; emit('extract', { text: text.value.trim(), url: url.value.trim(), file: file.value }); }
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[880px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" @submit.prevent="submit"><header class="flex items-start justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold">AI bóc tách giải thưởng</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">AI chỉ tạo bản nháp. Bạn kiểm tra và chủ động lưu ở bước sau.</p></div><MButton variant="neutral" :disabled="loading" @click="emit('cancel')">Hủy</MButton></header><div class="space-y-4 p-5"><label><span class="mb-1 block text-[13px] font-medium">Nội dung thông báo</span><MTextarea v-model="text" placeholder="Dán thể lệ hoặc thông báo giải thưởng…" :disabled="loading"/></label><label><span class="mb-1 block text-[13px] font-medium">Hoặc URL HTTPS</span><MInput v-model="url" type="url" placeholder="https://…" :disabled="loading"/></label><MUpload label="Hoặc tải tệp ảnh/PDF" accept="image/*,application/pdf" :multiple="false" :disabled="loading" @select-files="select"/><p v-if="file" class="text-[12px] text-[var(--mds-text-secondary)]">Đã chọn: {{ file.name }}</p><p v-if="error || localError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error || localError }}</p></div><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="loading" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="loading" @click="submit">Bóc tách thành bản nháp</MButton></footer></form></section></template>
